using WebullAnalytics.Pricing;
using WebullAnalytics.Pricing.Clock;
using Xunit;

namespace WebullAnalytics.Tests.Pricing;

/// <summary>The fitter must recover the clock that priced the books, and refuse to fit thin evidence. Books are generated by Black-76 on a
/// known trading-time clock with a constant vol, so the only thing distinguishing candidate clocks is how they carry variance overnight.</summary>
public class ClockFitterTests
{
	private static readonly ClockWeights TrueClock = new(0.20, 0.05);

	[Fact]
	public void RecoversTheClockThatPricedTheBooks()
	{
		var fit = ClockFitter.Fit("TEST", SyntheticDays(new DateOnly(2026, 1, 5), sessions: 130));
		Assert.NotNull(fit);
		Assert.InRange(fit!.Overnight, TrueClock.Overnight - 0.02, TrueClock.Overnight + 0.02);
		Assert.InRange(fit.NonTrading, TrueClock.NonTrading - 0.02, TrueClock.NonTrading + 0.02);
		Assert.True(fit.MaeFitted < fit.MaeCalendar / 5, $"fitted MAE {fit.MaeFitted} should be far below calendar {fit.MaeCalendar}");
	}

	[Fact]
	public void ThinHistory_DoesNotFit() => Assert.Null(ClockFitter.Fit("TEST", SyntheticDays(new DateOnly(2026, 1, 5), sessions: 20)));

	[Fact]
	public void BuildExpiryBook_ParityForward_AndOutOfTheMoneyBand()
	{
		var quotes = new List<(decimal, bool, decimal, decimal)>();
		foreach (var k in new[] { 95m, 98m, 100m, 102m, 105m, 120m })
		{
			var c = (decimal)Black(101.0, (double)k, 0.0004, true);
			var p = (decimal)Black(101.0, (double)k, 0.0004, false);
			quotes.Add((k, true, c - 0.01m, c + 0.01m));
			quotes.Add((k, false, Math.Max(0.01m, p - 0.01m), p + 0.01m));
		}
		var book = ClockStore.BuildExpiryBook(new DateOnly(2026, 2, 20), quotes)!;
		Assert.Equal(101.0, (double)book.Forward, 2);
		Assert.All(book.Options, o => Assert.Equal(o.Strike >= book.Forward, o.IsCall));
		Assert.DoesNotContain(book.Options, o => o.Strike == 120m);   // outside the ±5% band
	}

	/// <summary>Consecutive sessions from <paramref name="start"/>, each with a 16:00 and a 09:46 book for weekly expiries up to 60 days
	/// out, a slowly drifting forward, and every option priced at σ = 0.20 on <see cref="TrueClock"/>.</summary>
	private static List<ClockDay> SyntheticDays(DateOnly start, int sessions)
	{
		var days = new List<ClockDay>();
		var forward = 100.0;
		var d = start;
		while (days.Count < sessions)
		{
			if (MarketCalendar.IsOpen(d.ToDateTime(TimeOnly.MinValue)))
			{
				var open = Books(d, d.ToDateTime(ClockStore.OpenTime), forward);
				forward *= 1.0005;
				var close = Books(d, d.ToDateTime(ClockStore.CloseTime), forward);
				days.Add(new ClockDay(d, close, open));
			}
			d = d.AddDays(1);
		}
		return days;
	}

	private static List<ClockExpiryBook> Books(DateOnly date, DateTime at, double forward)
	{
		var books = new List<ClockExpiryBook>();
		for (var e = date; e.DayNumber - date.DayNumber <= 60; e = e.AddDays(1))
		{
			if (e.DayOfWeek != DayOfWeek.Friday || !MarketCalendar.IsOpen(e.ToDateTime(TimeOnly.MinValue))) continue;
			var expiryAt = e.ToDateTime(TimeOnly.MinValue) + MarketCalendar.CloseTimeEt(e.ToDateTime(TimeOnly.MinValue));
			if (expiryAt <= at) continue;
			var variance = 0.04 * MarketClock.Between(TrueClock, at, expiryAt).VarianceYears;
			var options = new List<ClockQuote>();
			for (var k = Math.Round(forward * 0.96); k <= forward * 1.04; k += 1)
			{
				var isCall = k >= forward;
				var mid = (decimal)Math.Round(Black(forward, k, variance, isCall), 4);
				if (mid < 0.06m) continue;
				options.Add(new ClockQuote((decimal)k, isCall, mid - 0.005m, mid + 0.005m));
			}
			books.Add(new ClockExpiryBook(e, (decimal)forward, options));
		}
		return books;
	}

	private static double Black(double f, double k, double variance, bool isCall) =>
		OptionMath.BlackScholesValue(f, k, OptionTime.Calendar(1.0), 0.0, Math.Sqrt(variance), isCall);
}
